#include <iostream>

int pagesAfterSession(int startingPages, int sessionPages)
{
    int total{startingPages + sessionPages};
    return total;
}

int main()
{
    int pages{12};
    int updatedPages{pagesAfterSession(pages, 8)};

    std::cout << "Before: " << pages << "\n";
    std::cout << "After: " << updatedPages << "\n";
}
